import { cookies } from 'next/headers';
import type { Metadata } from 'next';
import { resolveServerLocale } from '@/lib/i18n/server';
import { loadServerMultype } from '@/features/datamine/data';
import { MultypeView } from '@/features/datamine/multype';
import { buildMetadata } from '@/lib/seo';
import { MULTYPE_COPY } from '@/features/datamine/multype';

// Multype is regenerated by the local data pipeline while the application is
// running. Do not retain a prerendered RSC payload with the previous dataset.
export const dynamic = 'force-dynamic';

export async function generateMetadata(): Promise<Metadata> {
  const { locale } = await resolveServerLocale();
  return buildMetadata({
    title: 'Damage types',
    description: MULTYPE_COPY[locale].subtitle,
    path: '/datamine/multype/',
  });
}


export default async function MultypePage({
  searchParams,
}: {
  searchParams?: Promise<Record<string, string | string[] | undefined>>;
}) {
  const { locale } = await resolveServerLocale();
  const cookieStore = await cookies();
  const cookieTheme = cookieStore.get('tof-multype-theme')?.value;
  const params = (searchParams ? await searchParams : undefined) || {};
  const first = (value: string | string[] | undefined) =>
    Array.isArray(value) ? (value[0] ?? null) : (value ?? null);
  const requestedMode = first(params.mode);
  const initialMode = requestedMode === 'combined' || requestedMode === 'datamined' || requestedMode === 'renamed'
    ? requestedMode
    : 'ai-guess';
  const renameRaw = first(params.rename);
  const elementRaw = (first(params.element) || '').split(',')[0].toLowerCase();
  const requestedPalette = first(params.palette) || first(params.theme) || cookieTheme;
  const initialPalette = requestedPalette === 'light' || requestedPalette === 'dark' ? requestedPalette : 'dark';
  const initialData = await loadServerMultype(locale, { throwOnNotFound: false });

  return (
    <MultypeView
      initialData={initialData}
      initialLocale={locale}
      initialMode={initialMode}
      initialSearch={first(params.q)}
      initialMainFilter={first(params.main)}
      initialSubFilter={first(params.sub)}
      initialRenameFilter={
        renameRaw === 'all' || renameRaw === 'renamed' || renameRaw === 'unrenamed' ? renameRaw : null
      }
      initialElementFilter={
        ['all', 'final', 'fire', 'ice', 'volt', 'phys', 'super'].includes(elementRaw)
          ? (elementRaw as 'all' | 'final' | 'fire' | 'ice' | 'volt' | 'phys' | 'super')
          : null
      }
      initialPalette={initialPalette}
    />
  );
}
